export function getLawPost(slug: string) {
  return lawPosts.find((post) => post.slug === slug);
}

export function formatLawDate(date: string) {
  return new Date(date + "T00:00:00").toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  });
}
